import{_ as i,c as s,o as a,b0 as e}from"./chunks/framework.CLL9SSSf.js";const d="/linux-driver-docs/assets/image-20250410112827564.Dj2ZzYgy.png",l="/linux-driver-docs/assets/image-20250410113333002.ChTdPzZo.png",n="/linux-driver-docs/assets/image-20250410151200644.D_2TybjM.png",r="/linux-driver-docs/assets/image-20250410151224900.BHL6rsnj.png",h="/linux-driver-docs/assets/image-20250410150118893.D_PaCZov.png",p="/linux-driver-docs/assets/012_lcd_controller_timing.B60EAB2J.png",k="/linux-driver-docs/assets/image-20250410141911816.DZyQaupU.png",o="/linux-driver-docs/assets/image-20250410142908317.DX9TJ5Jv.png",c="/linux-driver-docs/assets/image-20250410143325033.weO7fftW.png",g="/linux-driver-docs/assets/image-20250410155353414.BqgJVeF2.png",C="/linux-driver-docs/assets/image-20250410165527136.BwJl7fE_.png",L="/linux-driver-docs/assets/image-20250410165950626.DHzx20sE.png",y="/linux-driver-docs/assets/image-20250411111347791.BsHPHFZL.png",B=JSON.parse('{"title":"LV055-LCD时序分析","description":null,"frontmatter":{"title":"LV055-LCD时序分析","date":"2026-01-21T20:53:29.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/kdriver/drv-video/126d2d53da51078bb6a31ae1","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-21T20:53:29.120Z","fulluuid":"bb6a31ae163645418733005ad9a3ad50","useduuid":"bb6a31ae1"}},"headers":[],"relativePath":"sdoc/kdriver/drv-video/126d2d53da51078bb6a31ae1.md","filePath":"sdoc/07-设备驱动子系统/09-video/LV055-LCD时序分析.md","lastUpdated":1769002717000}'),E={name:"sdoc/kdriver/drv-video/126d2d53da51078bb6a31ae1.md"};function D(F,t,b,_,m,u){return a(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="lv055-lcd时序分析" tabindex="-1">LV055-LCD时序分析 <a class="header-anchor" href="#lv055-lcd时序分析" aria-label="Permalink to &quot;LV055-LCD时序分析&quot;">​</a></h1><p>来学习一下 LCD 的时序？若笔记中有错误或者不合适的地方，欢迎批评指正 😃。</p><h2 id="一、我使用的-lcd-屏" tabindex="-1">一、我使用的 LCD 屏 <a class="header-anchor" href="#一、我使用的-lcd-屏" aria-label="Permalink to &quot;一、我使用的 LCD 屏&quot;">​</a></h2><h3 id="_1-硬件原理图" tabindex="-1">1. 硬件原理图 <a class="header-anchor" href="#_1-硬件原理图" aria-label="Permalink to &quot;1. 硬件原理图&quot;">​</a></h3><p>ALPHA 底板载了 RGB LCD 接口，此部分电路如图 ：</p><img src="'+d+'" alt="image-20250410112827564" style="zoom:50%;"><p>RGBLCD 就是 RGB LCD 接口，采用 RGB888 数据格式，并支持触摸屏（支持电阻屏和电容屏）。该接口仅支持 RGB 接口的液晶（不支持 MCU 接口的液晶），目前正点原子的 RGB 接口 LCD 模块有： 4.3 寸（ID: 4342， 480*272 和 ID: 4384， 800*480）、 7 寸(ID: 7084， 800*480 和 ID: 7016， 1024*600)和 10 寸(ID: 1018， 1280*800)等尺寸可选。</p><h3 id="_2-atk-md0430r-模块" tabindex="-1">2. ATK-MD0430R 模块 <a class="header-anchor" href="#_2-atk-md0430r-模块" aria-label="Permalink to &quot;2. ATK-MD0430R 模块&quot;">​</a></h3><h4 id="_2-1-模块简介" tabindex="-1">2.1 模块简介 <a class="header-anchor" href="#_2-1-模块简介" aria-label="Permalink to &quot;2.1 模块简介&quot;">​</a></h4><p>我使用的是 800*480 的 4.3 寸屏：</p><img src="'+l+'" alt="image-20250410113333002" style="zoom:50%;"><p>该模块 <strong>不带控制器</strong>，所以只能用于那些自带显示控制器的 MCU 或者 CPU，比如 ST 的 STM32F4x9， STM32F7x6 和 STM32H7x3 等。该 <strong>模块没显存</strong>，所以在使用的时候需要提供外部 RAM 来作为显示屏的显存。模块采用电容触摸屏，支持 5 点同时触摸，具有非常好的操控效果。ATK-MD0430R 模块还提供了背光控制功能。各项参数如下：</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>接口类型</td><td>LCD：并行 24 位 RGB 接口 触摸屏： IIC</td></tr><tr><td>颜色格式</td><td>RGB888（也可以用 RGB565）</td></tr><tr><td>颜色深度</td><td>最大 24 位</td></tr><tr><td>显存容量</td><td>无显存 1</td></tr><tr><td>LCD 分辨率</td><td>480*272 或 800*480</td></tr><tr><td>触摸屏类型</td><td>电容触摸</td></tr><tr><td>触摸点数</td><td>最多 5 点同时触摸</td></tr><tr><td>工作温度</td><td>-20℃~70℃</td></tr><tr><td>存储温度</td><td>-30℃~80℃</td></tr><tr><td>外形尺寸</td><td>68mm*118mm</td></tr></tbody></table><blockquote><p>在使用的时候需要提供外部 RAM 来作为 LCD 的显存！</p></blockquote><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>电源电压</td><td>5± 0.5V</td></tr><tr><td>IO 口电平</td><td>3.3V LVTTL</td></tr><tr><td>功耗</td><td>ATK-DM0430R-480232： 40~165mA； ATK-DM0430R-800480： 120~320mA</td></tr></tbody></table><blockquote><p>注 1： 3.3V 系统，可以直接接本模块（供电必须 5V），如果是 5V 系统，建议串接 100R 左右电阻，做限流处理。</p><p>注 2： 40mA 和 120mA 对应背光关闭时的功耗， 165mA 和 320mA 对应背光最亮时的功耗，此数据是在电源电压为 5V 时测出的，实际应用中功耗会由于电源电压的波动而略微变化。</p></blockquote><h4 id="_2-2-引脚说明" tabindex="-1">2.2 引脚说明 <a class="header-anchor" href="#_2-2-引脚说明" aria-label="Permalink to &quot;2.2 引脚说明&quot;">​</a></h4><p>模块通过 40P FPC 接口同外部连接，各引脚的详细描述如表 ：</p><table tabindex="0"><thead><tr><th>序号</th><th>名称</th><th>说明</th></tr></thead><tbody><tr><td>1,2</td><td>VCC5</td><td>5V 电源输入引脚。</td></tr><tr><td>3~10</td><td>R0~R7</td><td>8 位 RED 数据线。</td></tr><tr><td>11</td><td>GND</td><td>地线。</td></tr><tr><td>12~19</td><td>G0~G7</td><td>8 位 GREEN 数据线。</td></tr><tr><td>20</td><td>GND</td><td>地线</td></tr><tr><td>21~28</td><td>B0~B7</td><td>8 位 BLUE 数据线。</td></tr><tr><td>29</td><td>GND</td><td>地线。</td></tr><tr><td>30</td><td>CLK</td><td>像素时钟。</td></tr><tr><td>31</td><td>HSYNC</td><td>水平同步信号。</td></tr><tr><td>32</td><td>VSYNC</td><td>垂直同步信号。</td></tr><tr><td>33</td><td>DE</td><td>数据使能信号。</td></tr><tr><td>34</td><td>BL</td><td>背光控制信号。</td></tr><tr><td>35</td><td>CS</td><td>电容触摸屏复位信号(CT_RST)</td></tr><tr><td>36</td><td>MOSI</td><td>电容触摸屏 IIC_SDA 信号(CT_SDA)</td></tr><tr><td>37</td><td>MISO</td><td>NC，电容触摸屏未用到</td></tr><tr><td>38</td><td>SCK</td><td>电容触摸屏 IIC_SCL 信号(CT_SCL)</td></tr><tr><td>39</td><td>PEN</td><td>电容触摸屏中断信号(CT_INT)</td></tr><tr><td>40</td><td>RESET</td><td>LCD 复位信号（低电平有效）</td></tr></tbody></table><p>从上表可以看出， LCD 控制器总共需要 29 个 IO 口驱动（RGB888 格式），电容触摸屏需要 4 个 IO 口驱动，这样整个模块需要 33 个 IO 口驱动。注意：该模块的数据线 R7、 G7 和 B7 可以用于区分 RGB 屏的类型（可以看做是 ID）。MCU 在初始化 RGB 屏参数之前，先读取 R7/G7/B7 的状态，从而判断 RGB 屏类型，对应关系如表 :</p><table tabindex="0"><thead><tr><th style="text-align:center;">M2(B7)</th><th style="text-align:center;">M1(G7)</th><th style="text-align:center;">M0(R7)</th><th>RGBLCD 模块参数</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td>4.3 寸， 480*272 分辨率（RGB）</td></tr><tr><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td>7 寸， 800*480 分辨率（RGB）</td></tr><tr><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td>7 寸， 1024*600 分辨率（RGB）</td></tr><tr><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td style="text-align:center;">1</td><td>7 寸， 1280*800 分辨率（RGB）</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td>4.3 寸， 800*480 分辨率（RGB）</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td>10.1 寸 1280*800 分辨率（RGB）</td></tr><tr><td style="text-align:center;">X</td><td style="text-align:center;">X</td><td style="text-align:center;">X</td><td>暂时未用到</td></tr></tbody></table><p>由表可知，我们可以通过读取 R7/G7/B7 来判断 LCD 的尺寸和分辨率，从而使得 MCU 可以在同一个程序里面，兼容不同尺寸和分辨率的 RGB 屏。 从表可知， ATK-MD0430R-480272 屏幕 ID 为 000，而 ATK-MD0430R-800480 屏幕 ID 为 100。</p><h4 id="_2-3-接口时序表" tabindex="-1">2.3 接口时序表 <a class="header-anchor" href="#_2-3-接口时序表" aria-label="Permalink to &quot;2.3 接口时序表&quot;">​</a></h4><p>ATK-MD0430R-800480 模块采用 24 位并行 RGB 接口， 该接口的时序如表 ：</p><img src="'+n+'" alt="image-20250410151200644" style="zoom:80%;"><p>fclk、 Tvb、 Tvfp、 Thbp、 Thfp 这五个参数很重要， 在写驱动程序的时候会使用其配置 RGBLCD 的时序。ATK-MD0430R-800480 模块的输入信号特性如表 ：</p><img src="'+r+'" alt="image-20250410151224900" style="zoom:80%;"><p>最重要的两个参数就是 Thwh 和 Tvwh，这两个就是 hsw 和 vsw， 在写程序的时候需要用到。</p><h3 id="_3-芯片手册" tabindex="-1">3. 芯片手册 <a class="header-anchor" href="#_3-芯片手册" aria-label="Permalink to &quot;3. 芯片手册&quot;">​</a></h3><p>这个模块的裸屏规格书是这个 WKS43235。这里有个在线的：<a href="https://max.book118.com/html/2023/0523/7036140066005111.shtm" target="_blank" rel="noreferrer">4.3 寸 800480 裸屏规格书.pdf-原创力文档</a>（或者看我的仓库：<a href="https://gitee.com/sumumm/imx6ull-bare-demo/raw/master/21_lcd/ATK-MD0430R-800480%E8%A3%B8%E5%B1%8F%E8%B5%84%E6%96%99/4.3%E5%AF%B8800480%E8%A3%B8%E5%B1%8F%E8%A7%84%E6%A0%BC%E4%B9%A6.pdf" target="_blank" rel="noreferrer">WKS43235_SPEC_V0.0.doc</a>）。规格书里面没有写这个 LCD 屏幕使用的驱动 IC：</p><img src="'+h+'" alt="image-20250410150118893" style="zoom:50%;"><p>不过模块资料里面给了 ST7262 的芯片手册，这里有一个在线的芯片手册： <a href="https://www.orientdisplay.com/pdf/ST7262.pdf" target="_blank" rel="noreferrer">ST7262</a>（或者看我的仓库：<a href="https://gitee.com/sumumm/imx6ull-bare-demo/raw/master/21_lcd/ATK-MD0430R-800480%E8%A3%B8%E5%B1%8F%E8%B5%84%E6%96%99/4.3%E5%AF%B8800480%E8%A3%B8%E5%B1%8F%E9%A9%B1%E5%8A%A8IC-ST7262.pdf" target="_blank" rel="noreferrer">ST7262</a>）。这个应该是用于驱动裸屏的把。时序也可以在这个芯片手但是册中找到（但是吧，上面的时序相关的表和这个芯片的手册貌似有点对不上，我也不搞不懂了，但是提供的资料里面的裸屏 IC 驱动芯片的芯片手册就是这个，反正原理都类似）。</p><h2 id="二、lcd-时序分析" tabindex="-1">二、LCD 时序分析 <a class="header-anchor" href="#二、lcd-时序分析" aria-label="Permalink to &quot;二、LCD 时序分析&quot;">​</a></h2><h3 id="_1-时间参数" tabindex="-1">1. 时间参数 <a class="header-anchor" href="#_1-时间参数" aria-label="Permalink to &quot;1. 时间参数&quot;">​</a></h3><p>先来看一下下面的一张图：</p><img src="'+p+'" alt="image-20210109154234559" style="zoom:50%;"><p>如果将 LCD 显示一帧图像的过程想象成绘画，那么在显示的过程中就是用一根“笔”在不同的像素点画上不同的颜色。这根笔按照从左至右、从上到下的顺序扫描每个像素点，并且在像素画上对应的颜色，当画到最后一个像素点的时候一幅图像就绘制好了。 我们来看一下 LCD 是怎么扫描显示一帧图像的。</p><h4 id="_1-1-水平同步信号-hsync" tabindex="-1">1.1 水平同步信号 HSYNC <a class="header-anchor" href="#_1-1-水平同步信号-hsync" aria-label="Permalink to &quot;1.1 水平同步信号 HSYNC&quot;">​</a></h4><p>一帧图像也是由一行一行组成的。 HSYNC 是水平同步信号，也叫做 <strong>行同步信号</strong>，当产生此信号的话就表示开始显示新的一行了，所以此信号都是在图的最左边。它表示液晶屏一行像素数据的传输结束，<strong>每传输完成液晶屏的一行像素数据时， HSYNC 会发生电平跳变</strong>，如分辨率为 800x480 的显示屏(800 列，480 行)，传输一帧的图像 HSYNC 的电平会跳变 480 次。</p><h4 id="_1-2-垂直同步信号-vsync" tabindex="-1">1.2 垂直同步信号 VSYNC <a class="header-anchor" href="#_1-2-垂直同步信号-vsync" aria-label="Permalink to &quot;1.2 垂直同步信号 VSYNC&quot;">​</a></h4><p>VSYNC 信号是垂直同步信号，也叫做 <strong>帧同步信号</strong>，当产生此信号的话就表示开始显示新的一帧图像了 。垂直同步信号 VSYNC(Vertical Sync)用于表示液晶屏一帧像素数据的传输结束，每传输完成一帧像素数据时， VSYNC 会发生电平跳变。其中“帧”是图像的单位，一幅图像称为一帧，在液晶屏中，一帧指一个完整屏液晶像素点。 我们常常用“帧/秒”来表示液晶屏的刷新特性，即液晶屏每秒可以显示多少帧图像，如液晶屏以 60 帧/秒的速率运行时， VSYNC 每秒钟电平会跳变 60 次。</p><h4 id="_1-3-hbp、-hfp、-vbp-和-vfp" tabindex="-1">1.3 HBP、 HFP、 VBP 和 VFP <a class="header-anchor" href="#_1-3-hbp、-hfp、-vbp-和-vfp" aria-label="Permalink to &quot;1.3 HBP、 HFP、 VBP 和 VFP&quot;">​</a></h4><p>接下来看这四个参数。其实上面的那张图不是很明显，我们看下这张：</p><img src="'+k+'" alt="image-20250410141911816" style="zoom:80%;"><p>和上面是一样的，只是，多了一圈“黑边”。真正有效的显示区域是中间的白色部分。那这一圈“黑边”是什么东西呢？这就要从显示器的“祖先” CRT 显示器开始说起了， CRT 显示器就是以前很常见的那种大屁股显示器，在现在应该很少见了，如果在农村有可能应该还是可以见到的。</p><p>CRT 显示器屁股后面是个电子枪，这个电子枪就是我们上面说的“画笔”，电子枪打出的电子撞击到屏幕上的荧光物质使其发光。只要控制电子枪从左到右扫完一行(也就是扫描一行)，然后从上到下扫描完所有行，这样一帧图像就显示出来了。也就是说，显示一帧图像电子枪是按照‘Z’形在运动，当扫描速度很快的时候看起来就是一幅完成的画面了。</p><p>当显示完一行以后会发出 HSYNC 信号，此时电子枪就会关闭，然后迅速的移动到屏幕的左边，当 HSYNC 信号结束以后就可以显示新的一行数据了，电子枪就会重新打开。在 HSYNC 信号结束到电子枪重新打开之间会插入一段延时，这段延时就是图中的 <strong>HBP</strong> 。</p><p>当显示完一行以后就会关闭电子枪等待 HSYNC 信号产生，关闭电子枪到 HSYNC 信号产生之间会插入一段延时，这段延时就是图中的 <strong>HFP</strong> 信号。</p><p>同理，当显示完一帧图像以后电子枪也会关闭，然后等到 VSYNC 信号产生，期间也会加入一段延时，这段延时就是图中的 <strong>VFP</strong>。</p><p>VSYNC 信号产生，电子枪移动到左上角，当 VSYNC 信号结束以后电子枪重新打开，中间也会加入一段延时，这段延时就是图中的 <strong>VBP</strong>。</p><p>HBP、 HFP、 VBP 和 VFP 就是导致图中黑边的原因，但是这是 CRT 显示器存在黑边的原因，现在是 LCD 显示器，不需要电子枪了，那么为何还会有黑边？这是因为 RGB LCD 屏幕内部是有一个 IC 的，发送一行或者一帧数据给 IC， IC 是需要反应时间的。通过这段反应时间可以让 IC 识别到一行数据扫描完了，要换行了，或者一帧图像扫描完了，要开始下一帧图像显示了。因此，在 LCD 屏幕中继续存在 HBP、 HFP、 VPB 和 VFP 这四个参数的主要目的是为了 <strong>锁定有效的像素数据</strong>。</p><p>这四个时间是 LCD 重要的时间参数，后面编写 LCD 驱动的时候要用到的，至于这四个时间参数具体值是多少，那要需要去查看所使用的 LCD 数据手册了。</p><h4 id="_1-4-rgb-lcd-屏幕时序" tabindex="-1">1.4 RGB LCD 屏幕时序 <a class="header-anchor" href="#_1-4-rgb-lcd-屏幕时序" aria-label="Permalink to &quot;1.4 RGB LCD 屏幕时序&quot;">​</a></h4><h5 id="_1-4-1-行显示时序" tabindex="-1">1.4.1 行显示时序 <a class="header-anchor" href="#_1-4-1-行显示时序" aria-label="Permalink to &quot;1.4.1 行显示时序&quot;">​</a></h5><p>上面了解了行显示和帧显示，我们来看一下 <strong>行显示对应的时序图</strong>：</p><img src="'+o+'" alt="image-20250410142908317"><p>上图就是 RGB LCD 的行显示时序，我们来分析一下其中重要的几个参数：</p><ul><li>HSYNC：行同步信号，当此信号有效的话就表示开始显示新的一行数据，查阅所使用的 LCD 数据手册可以知道此信号是低电平有效还是高电平有效，假设此时是低电平有效。</li><li>HSPW： 有些地方也叫做 thp，是 HSYNC 信号宽度，也就是 HSYNC 信号持续时间。 HSYNC 信号不是一个脉冲，而是需要持续一段时间才是有效的，单位为 CLK。</li><li>HBP： 有些地方叫做 thb，前面已经学习过了，术语叫做行同步信号后肩，单位是 CLK。</li><li>HOZVAL：有些地方叫做 thd，显示一行数据所需的时间，假如屏幕分辨率为 1024*600，那么 HOZVAL 就是 1024，单位为 CLK。</li><li>HFP：有些地方叫做 thf，前面已经学习过了， 术语叫做行同步信号前肩，单位是 CLK。</li><li>CLK：同步时钟信号 CLK，液晶屏与外部使用同步通讯方式，以 CLK 信号作为同步时钟，在同步时钟的驱动下，每个时钟传输一个像素点数据。</li><li>DE：数据使能信号 DE(Data Enable)用于表示数据的有效性，当 DE 信号线为高电平时，RGB 信号线表示的数据有效。</li></ul><p>当 HSYNC 信号发出以后，需要等待 HSPW+HBP 个 CLK 时间才会接收到真正有效的像素数据。当显示完一行数据以后需要等待 HFP 个 CLK 时间才能发出下一个 HSYNC 信号。</p><p>所以 <strong>显示一行所需要的时间</strong> 就是： <code>HSPW + HBP + HOZVAL + HFP</code>。</p><h5 id="_1-4-2-帧显示时序" tabindex="-1">1.4.2 帧显示时序 <a class="header-anchor" href="#_1-4-2-帧显示时序" aria-label="Permalink to &quot;1.4.2 帧显示时序&quot;">​</a></h5><p>一帧图像就是由很多个行组成的， RGB LCD 的帧显示时序 ：</p><img src="'+c+'" alt="image-20250410143325033"><p>上图就是 RGB LCD 的帧显示时序，我们来分析一下其中重要的几个参数：</p><ul><li>VSYNC：帧同步信号，当此信号有效的话就表示开始显示新的一帧数据，查阅所使用的 LCD 数据手册可以知道此信号是低电平有效还是高电平有效，假设此时是低电平有效。</li><li>VSPW： 有些地方也叫做 tvp，是 VSYNC 信号宽度，也就是 VSYNC 信号持续时间，单位为 1 行的时间。</li><li>VBP： 有些地方叫做 tvb，前面已经学习过了，术语叫做帧同步信号后肩，单位为 1 行的时间。</li><li>LINE： 有些地方叫做 tvd，显示一帧有效数据所需的时间，假如屏幕分辨率为 1024*600，那么 LINE 就是 600 行的时间。</li><li>VFP： 有些地方叫做 tvf，前面已经学习过了，术语叫做帧同步信号前肩，单位为 1 行的时间。</li></ul><p><strong>显示一帧所需要的时间</strong> 就是： <code>VSPW+VBP+LINE+VFP</code> 个行时间，最终的计算公式：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (VSPW+VBP+LINE+VFP) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HSPW</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HBP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HOZVAL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HFP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-像素时钟" tabindex="-1">2. 像素时钟 <a class="header-anchor" href="#_2-像素时钟" aria-label="Permalink to &quot;2. 像素时钟&quot;">​</a></h3><h4 id="_2-1-怎么计算" tabindex="-1">2.1 怎么计算？ <a class="header-anchor" href="#_2-1-怎么计算" aria-label="Permalink to &quot;2.1 怎么计算？&quot;">​</a></h4><p>像素时钟就是 RGB LCD 的时钟信号，以 ATK7016 这款屏幕为例：</p><img src="'+g+`" alt="image-20250410155353414"><p>显示一帧图像所需要的时钟数就是：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLK_NUM </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (VSPW</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VBP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VFP) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (HSPW </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HBP </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HOZVAL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HFP)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 140</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 160</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 635</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1344</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 853440</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>显示一帧图像需要 853440 个时钟数，那么显示 60 帧就是： 853440 * 60 = 51206400≈51.2M，所以像素时钟就是 51.2MHz。</p><h4 id="_2-2-时钟怎么来的" tabindex="-1">2.2 时钟怎么来的？ <a class="header-anchor" href="#_2-2-时钟怎么来的" aria-label="Permalink to &quot;2.2 时钟怎么来的？&quot;">​</a></h4><p>I.MX6U 是可以通过 eLCDIF 来控制 LCD， 这个 eLCDIF 控制器后面再说，想先来看一下 eLCDIF 接口时钟图：</p><img src="`+C+'" alt="image-20250410165527136"><p>①、此部分是一个选择器，用于选择哪个 PLL 可以作为 LCDIF 时钟源，由寄存器 CCM_CSCDR2 的位 LCDIF1_PRE_CLK_SEL(bit17:15)来决定， LCDIF1_PRE_CLK_SEL 选择设置如表</p><table tabindex="0"><thead><tr><th style="text-align:center;">值</th><th style="text-align:center;">时钟源</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">PLL2 作为 LCDIF 的时钟源。</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">PLL3_PFD3 作为 LCDIF 的时钟源。</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">PLL5 作为 LCDIF 的时钟源。</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">PLL2_PFD0 作为 LCDIF 的时钟源。</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">PLL2_PFD1 作为 LCDIF 的时钟源。</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">PLL3_PFD1 作为 LCDIF 的时钟源。</td></tr></tbody></table><p>②、 此部分是 LCDIF 时钟的预分频器，由寄存器 CCM_CSCDR2 的位 LCDIF1_PRED 来决定预分频值。 可设置值为 0~7，分别对应 1~8 分频。</p><p>③、 此部分进一步分频，由寄存器 CBCMR 的位 LCDIF1_PODF 来决定分频值。 可设置值为 0~7，分别对应 1~8 分频。</p><p>④、此部分是一个选择器，选择 LCDIF 最终的根时钟，由寄存器 CSCDR2 的位 LCDIF1_CLK_SEL 决定， LCDIF1_CLK_SEL 选择设置如表所示：</p><table tabindex="0"><thead><tr><th style="text-align:center;">值</th><th style="text-align:center;">时钟源</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">前面复用器出来的时钟，也就是前面 PLL5 出来的时钟作为 LCDIF 的根时钟。</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">ipp_di0_clk 作为 LCDIF 的根时钟。</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">ipp_di1_clk 作为 LCDIF 的根时钟。</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">ldb_di0_clk 作为 LCDIF 的根时钟。</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">ldb_di1_clk 作为 LCDIF 的根时钟。</td></tr></tbody></table><p>里肯定选择 PLL5 出来的那一路时钟作为 LCDIF 的根时钟，因此 LCDIF1_CLK_SEL 设置为 0。 LCDIF 既然选择了 PLL5 作为时钟源，那么还需要初始化 PLL5， LCDIF 的时钟是由 PLL5 和图 24.1.1.8 中的 ②、③ 这两个分频值决定的，所以需要对这三个进行合理的设置以搭配出所需的时钟值，我们就以 ATK7016 屏幕所需的 51.2MHz 为例，看看如何进行配置。</p><p>PLL5 频率设置涉及到四个寄存器： CCM_PLL_VIDEO、 CCM_PLL_VIDEO_NUM、CCM_PLL_VIDEO_DENOM 、 CCM_MISC2 。 其 中 CCM_PLL_VIDEO_NUM 和 CCM_PLL_VIDEO_DENOM 这两个寄存器是用于小数分频的，我们这里为了简单不使用小数分频，因此这两个寄存器设置为 0。</p><p>PLL5 的时钟计算公式如下：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PLL5_CLK</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OSC24M</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (loopDivider </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (denominator </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> numerator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) / postDivider</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>不使用小数分频的话 PLL5 时钟计算公式就可以简化为 ：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PLL5_CLK</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OSC24M</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> loopDivider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postDivider</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>OSC24M 就是 24MHz 的有源晶振，现在的问题就是设置 loopDivider 和 postDivider。先来看一下寄存器 CCM_PLL_VIDEO，此寄存器结构如图（参考手册的18.7.11 Analog Video PLL control Register）:</p><img src="'+L+`" alt="image-20250410165950626" style="zoom:50%;"><p>寄存器 CCM_PLL_VIDEO 用到的重要的位如下：</p><ul><li>POST_DIV_SLECT(bit20:19)： 此位和寄存器 CCM_ANALOG_CCMSC2 的 VIDEO_DIV 位共同决定了 postDivider，为 0 的话是 4 分频，为 1 的话是 2 分频，为 2 的话是 1 分频。本章设置为 2，也就是 1 分频。</li><li>ENABLE(bit13)： PLL5(PLL_VIDEO)使能位，为 1 的话使能 PLL5，为 0 的话关闭 PLL5。</li><li>DIV_SELECT(bit6:0)： loopDivider 值，范围为 27~54，这里需要设置为 32。寄存器 CCM_ANALOG_MISC2 的位 VIDEO_DIV(bit31:30)与寄存器 CCM_PLL_VIDEO 的位 POST_DIV_SLECT(bit20:19)共同决定了 postDivider，通过这两个的配合可以获得 2、 4、 8、16 分频。</li></ul><p>这里将 VIDEO_DIV 设置为 0，也就是 1 分频，因此 postDivider 就是 1， loopDivider 设置为 32， PLL5 的时钟频率就是：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PLL5_CLK </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OSC24M </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> loopDivider </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> postDivider</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">         =</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> 24M</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> /</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">         =</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> 768MHz</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>PLL5 此时为 768MHz，在经过图中的 ② 和 ③ 进一步分频，设置 ② 中为 3 分频，也就是寄存器 CCM_CSCDR2 的位 LCDIF1_PRED(bit14:12)为 2。设置 ③ 中为 5 分频，就是寄存器 CCM_CBCMR 的位 LCDIF1_PODF(bit25:23)为 4。设置好以后最终进入到 LCDIF 的时钟频率就是： 768/3/5 = 51.2MHz，这就是我们需要的像素时钟频率。</p><h3 id="_3-lcd-时序参数总结" tabindex="-1">3. LCD 时序参数总结 <a class="header-anchor" href="#_3-lcd-时序参数总结" aria-label="Permalink to &quot;3. LCD 时序参数总结&quot;">​</a></h3><p>如下图所示（左右两张图中 HSYNC 和 VSYNC 有效电平是可配置的，具体看手册，高低都有可能，左右两张图对比参考）：</p><p><img src="`+y+'" alt="image-20250411111347791"></p><table style="font-size:14px;"><tbody><tr><td width="70px" align="center"> 时序 </td><td width="200px" align="center"> 时间参数 </td><td width="120px" align="center"> 其他名称 </td><td align="center"> 参数说明 </td></tr><tr><td rowspan="5" align="center"> 行显示 </td><td align="center"> HSYNC<br>(Horizontal Sync)</td><td align="center">-</td><td align="left"> 行同步信号，一行像素数据的传输结束 </td></tr><tr><td align="center"> HSW<br>(horizontal sync width)</td><td align="center"> HSPW、thp </td><td align="left"> HSYNC 信号宽度，就是水平同步信号的宽度，单位为同步时钟 CLK 的个数 </td></tr><tr><td align="center"> HBP<br>(horizontal back porch)</td><td align="center"> thb </td><td align="left"> 表示从水平同步信号开始到一行的有效数据开始之间的 CLK 的个数（在 HSYNC 信号结束到电子枪重新打开之间插入的一段延时）</td></tr><tr><td align="center"> HOZVAL </td><td align="center"> thd </td><td align="left"> 显示一行数据所需的时间，假如屏幕分辨率为 1024*600，那么 HOZVAL 就是 1024，单位为 CLK。</td></tr><tr><td align="center"> HFP<br>(horizontal front porth)</td><td align="center"> thf </td><td align="left"> 表示一行的有效数据结束到下一个水平同步信号开始之间的 CLK 的个数（显示完一行以后就会关闭电子枪等待 HSYNC 信号产生，关闭电子枪到 HSYNC 信号产生之间插入的一段延时）。</td></tr><tr><td rowspan="5" align="center"> 帧显示 </td><td align="center"> VSYNC<br>(Vertical Sync)</td><td align="center">-</td><td align="left"> 帧同步信号，一帧像素数据的传输结束 </td></tr><tr><td align="center"> VSW<br>(vertical sync width)</td><td align="center"> VSPW、tvp </td><td align="left"> VSYNC 信号宽度，就是垂直同步信号的宽度，单位为 1 行的时间 </td></tr><tr><td align="center"> VBP<br>(vertical back porch)</td><td align="center"> tvb </td><td align="left"> 表示在一帧图像开始时，垂直同步信号以后的无效的行数，单位为 1 行的时间。（VSYNC 信号产生，电子枪移动到左上角，VSYNC 信号结束以后电子枪重新打开，中间加入的一段延时）</td></tr><tr><td align="center"> LINE </td><td align="center"> tvd </td><td align="left"> 显示一帧有效数据所需的时间，假如屏幕分辨率为 1024*600，那么 LINE 就是 600 行的时间。</td></tr><tr><td align="center"> VFP<br>(vertical front porch)</td><td align="center"> tvf </td><td align="left"> 表示在一帧图像结束后，垂直同步信号以前的无效的行数（当显示完一帧图像以后电子枪也会关闭，然后等到 VSYNC 信号产生，期间也会加入的一段延时）。</td></tr></tbody></table>',100)])])}const x=i(E,[["render",D]]);export{B as __pageData,x as default};
